// /sitemap.xml is one of two documents. On docs.n8n.io and developer.mozilla.org
// it is a <sitemapindex> whose <loc> entries are other sitemaps, not pages -
// crawl those as pages and you spend the whole run reading XML.
//
// single-item input: one sitemap was fetched.
const cfg = $('Settings').first().json;

function bodyOf(x) {
  if (x == null) { return ''; }
  if (typeof x === 'string') { return x; }
  if (typeof x.data === 'string') { return x.data; }
  if (typeof x.body === 'string') { return x.body; }
  return JSON.stringify(x);
}

const xml = bodyOf($input.first().json);
if (xml.indexOf('<loc') < 0) {
  throw new Error('No <loc> entries came back from ' + cfg.sitemap + '. A gzipped .xml.gz cannot be read here - point this at the plain XML.');
}

const isIndex = /<sitemapindex[\s>]/i.test(xml);
const locs = [...xml.matchAll(/<loc>\s*([^<\s]+)\s*<\/loc>/gi)].map(function (m) { return m[1]; });

return locs.slice(0, isIndex ? 10 : 20000).map(function (u) {
  return { json: { kind: isIndex ? 'child' : 'page', url: u } };
});

// Second pass, one item per child sitemap.
function bodyOf(x) {
  if (x == null) { return ''; }
  if (typeof x === 'string') { return x; }
  if (typeof x.data === 'string') { return x.data; }
  if (typeof x.body === 'string') { return x.body; }
  return JSON.stringify(x);
}

const out = [];
for (const item of $input.all()) {
  for (const m of bodyOf(item.json).matchAll(/<loc>\s*([^<\s]+)\s*<\/loc>/gi)) {
    out.push({ json: { kind: 'page', url: m[1] } });
  }
}

// A step that returns nothing ends the branch, and the Merge below would wait
// on an input that never arrives.
if (!out.length) { return [{ json: { kind: 'page', url: '' } }]; }
return out;

// Both sitemap shapes land here.
const cfg = $('Settings').first().json;
const cap = Math.max(1, Number(cfg.max_pages) || 40);
const must = String(cfg.url_must_contain || '').trim().toLowerCase();

const seen = new Set();
const out = [];
for (const item of $input.all()) {
  let u = String((item.json || {}).url || '').trim();
  if (!u || u.slice(0, 4) !== 'http') { continue; }
  u = u.split('#')[0];
  if (/\.(png|jpe?g|gif|svg|webp|pdf|zip|css|js|xml|json)$/i.test(u)) { continue; }
  if (must && u.toLowerCase().indexOf(must) < 0) { continue; }
  if (seen.has(u)) { continue; }
  seen.add(u);
  out.push({ json: { url: u } });
  if (out.length >= cap) { break; }
}
if (!out.length) {
  throw new Error('No pages left after filtering. Check sitemap and url_must_contain in Settings.');
}
return out;

// Every <a href> on every page, deduplicated by URL.
//
// Deduplication is the whole job. The navigation is on all forty pages, so the
// raw list is about two thousand links and a few hundred distinct ones -
// checking the same footer link forty times is forty requests and one fact.
//
// The Code sandbox has no `URL` class, so relative links are resolved by hand.
// All of these appear in real HTML and none of them behave the same:
//   //cdn.example.com/x   scheme-relative
//   /about                root-relative
//   ../pricing            parent-relative
//   ?page=2               query-only
//   #section              fragment-only, never a link to check
const cfg = $('Settings').first().json;
const maxLinks = Math.max(10, Number(cfg.max_links) || 400);
const external = cfg.check_external !== false;

function bodyOf(x) {
  if (x == null) { return ''; }
  if (typeof x === 'string') { return x; }
  if (typeof x.data === 'string') { return x.data; }
  if (typeof x.body === 'string') { return x.body; }
  return '';
}

function parts(u) {
  const m = String(u).match(/^(https?:)\/\/([^\/?#]+)([^?#]*)/i);
  return m ? { scheme: m[1], host: m[2], path: m[3] || '/' } : null;
}

// A share button is not a link to your content. Every page carries the same
// four, they all redirect (twitter.com to x.com, LinkedIn to a login page), and
// they were 9 of the first 11 findings on the first live run.
const SHARE = /(twitter\.com\/intent|x\.com\/intent|linkedin\.com\/(shareArticle|sharing\/share-offsite)|facebook\.com\/sharer|pinterest\.[a-z]+\/pin\/create|reddit\.com\/submit|t\.me\/share|wa\.me\/|api\.whatsapp\.com\/send|tumblr\.com\/share|buffer\.com\/add|news\.ycombinator\.com\/submitlink|mailto:)/i;

function resolve(href, pageUrl) {
  let h = String(href || '').trim();
  if (!h) { return ''; }
  if (/^(mailto:|tel:|javascript:|data:|sms:|ftp:)/i.test(h)) { return ''; }
  if (h.charAt(0) === '#') { return ''; }
  // An href in HTML is entity-encoded. `&amp;` in a query string is two
  // characters that do not belong in the request.
  h = h.replace(/&amp;/gi, '&').replace(/&#0*38;/g, '&').replace(/&quot;/gi, '"');
  if (SHARE.test(h)) { return ''; }
  const p = parts(pageUrl);
  if (!p) { return ''; }
  if (/^https?:\/\//i.test(h)) { return h.split('#')[0]; }
  if (h.slice(0, 2) === '//') { return (p.scheme + h).split('#')[0]; }
  if (h.charAt(0) === '/') { return (p.scheme + '//' + p.host + h).split('#')[0]; }
  if (h.charAt(0) === '?') { return (p.scheme + '//' + p.host + p.path + h).split('#')[0]; }
  // Relative to the page's directory, with ../ walked off the end of it.
  let dir = p.path.replace(/[^\/]*$/, '');
  while (h.slice(0, 3) === '../') {
    h = h.slice(3);
    dir = dir.replace(/[^\/]+\/$/, '');
  }
  if (h.slice(0, 2) === './') { h = h.slice(2); }
  return (p.scheme + '//' + p.host + dir + h).split('#')[0];
}

const pages = $('Pick The Pages To Crawl').all();
const fetched = $input.all();
if (pages.length !== fetched.length) {
  throw new Error('Asked for ' + pages.length + ' pages and got ' + fetched.length + ' responses. They are matched by position.');
}

const links = new Map();
let scanned = 0;
let dead = 0;

for (let i = 0; i < fetched.length; i++) {
  const pageUrl = String(((pages[i] || {}).json || {}).url || '');
  const html = bodyOf(fetched[i].json);
  if (!html) { dead++; continue; }
  const home = parts(pageUrl);
  for (const m of html.matchAll(/<a\b[^>]*href\s*=\s*["']([^"']+)["'][^>]*>/gi)) {
    const target = resolve(m[1], pageUrl);
    if (!target) { continue; }
    scanned++;
    const t = parts(target);
    if (!t) { continue; }
    const isInternal = home && t.host.toLowerCase() === home.host.toLowerCase();
    if (!isInternal && !external) { continue; }
    const key = target.replace(/\/$/, '').toLowerCase();
    const seen = links.get(key);
    if (seen) {
      if (seen.found_on.length < 3 && seen.found_on.indexOf(pageUrl) < 0) { seen.found_on.push(pageUrl); }
      seen.times++;
      continue;
    }
    links.set(key, { url: target, link_key: key, host: t.host, internal: isInternal, found_on: [pageUrl], times: 1 });
  }
}

if (!links.size) {
  throw new Error('Read ' + fetched.length + ' pages (' + dead + ' empty) and found no links at all. If the pages render in the browser rather than in the HTML, there is nothing here to check.');
}

// Most-linked first, so a capped run checks the navigation before it checks a
// footnote on one page.
const all = [...links.values()].sort(function (a, b) { return b.times - a.times; });
return all.slice(0, maxLinks).map(function (l) {
  return { json: Object.assign({}, l, { scanned: scanned, distinct: all.length }) };
});

// What came back, sorted into four piles rather than listed.
//
//   broken       404, 410, or nothing at all. Fix or remove these.
//   blocked      403, 429, 503. reddit.com and g2.com answer 403 to every
//                plain client, and a report that calls those broken is a
//                report nobody reads twice.
//   redirected   3xx whose target differs by more than a trailing slash, a
//                scheme or a www. Everything else is a redirect nobody needs
//                to know about.
//   ok           2xx.
const asked = $('Collect Every Link').all();
const got = $input.all();
if (asked.length !== got.length) {
  throw new Error('Checked ' + got.length + ' links out of ' + asked.length + '. They are matched by position.');
}

function normalise(u) {
  return String(u || '')
    .replace(/^https?:\/\//i, '')
    .replace(/^www\./i, '')
    .replace(/\/$/, '')
    .toLowerCase();
}

function origin(u) {
  const m = String(u).match(/^https?:\/\/[^\/]+/);
  return m ? m[0] : '';
}

const today = new Date().toISOString().slice(0, 10);
const out = [];

for (let i = 0; i < got.length; i++) {
  const link = (asked[i] || {}).json || {};
  const res = got[i].json || {};
  const status = Number(res.statusCode || 0);
  const headers = res.headers || {};

  let location = String(headers.location || headers.Location || '');
  if (location && location.charAt(0) === '/') { location = origin(link.url) + location; }

  let verdict = 'ok';
  let detail = '';

  if (!status) {
    verdict = 'broken';
    detail = 'The request did not complete. The host may no longer exist.';
  } else if (status === 404 || status === 410) {
    verdict = 'broken';
    detail = 'Returned ' + status + '.';
  } else if (status === 403 || status === 429 || status === 503 || status === 401 || status === 451 || status === 999) {
    verdict = 'blocked';
    // 999 is LinkedIn's. It is not in any RFC, it means "you are not a browser",
    // and it was the single "broken" link on the first live run - a profile
    // that opens perfectly well in a browser.
    detail = 'Returned ' + status + '. That is a bot wall rather than a dead page - open it yourself before changing anything.';
  } else if (status >= 300 && status < 400) {
    const same = normalise(location) === normalise(link.url);
    if (!location) {
      verdict = 'broken';
      detail = 'Returned ' + status + ' with no destination.';
    } else if (same) {
      verdict = 'ok';
      detail = 'Redirects to itself with a slash or a scheme changed. Not worth touching.';
    } else {
      verdict = 'redirected';
      detail = 'Returns ' + status + ' to ' + location + '. The link still works; every visitor takes an extra hop.';
    }
  } else if (status >= 400) {
    verdict = 'broken';
    detail = 'Returned ' + status + '.';
  }

  out.push({ json: {
    link_key: link.link_key,
    url: link.url,
    host: link.host,
    internal: !!link.internal,
    status: status,
    redirects_to: location,
    verdict: verdict,
    detail: detail,
    found_on: (link.found_on || []).join(' '),
    times: link.times || 1,
    last_seen: today,
  }});
}
return out;

// What is worth telling somebody about this week.
//
// The state table is what keeps this readable: a broken link stays broken until
// somebody fixes it, and reporting it every Monday for a month is how the
// report gets muted. A link is reported once per verdict, and again only if the
// verdict changes.
const rows = $('Judge Every Link').all().map(function (i) { return i.json; });

const before = new Map();
for (const r of $('Read What You Reported').all()) {
  const j = r.json || {};
  if (j.link_key) { before.set(String(j.link_key), j); }
}

const problems = rows.filter(function (r) { return r.verdict === 'broken' || r.verdict === 'redirected'; });
const fresh = problems.filter(function (r) {
  const seen = before.get(r.link_key);
  return !seen || String(seen.verdict) !== r.verdict;
});

// Never return zero items: the quiet branch below has to be reachable, and the
// counts have to survive to the report either way.
return [{ json: {
  has_news: fresh.length > 0,
  fresh: fresh,
  fresh_count: fresh.length,
  broken: rows.filter(function (r) { return r.verdict === 'broken'; }).length,
  redirected: rows.filter(function (r) { return r.verdict === 'redirected'; }).length,
  blocked: rows.filter(function (r) { return r.verdict === 'blocked'; }).length,
  ok: rows.filter(function (r) { return r.verdict === 'ok'; }).length,
  checked: rows.length,
}}];

// The report, with the noise counted instead of listed.
//
// single-item input: the step above folds the whole run into one item.
const cfg = $('Settings').first().json;
const s = $input.first().json;
const pages = $('Pick The Pages To Crawl').all().length;
const collected = ($('Collect Every Link').first().json || {});

const parts = ['*Link check on ' + cfg.sitemap + '*'];
parts.push(
  pages + ' pages, ' + (collected.scanned || 0) + ' links on them, ' +
  (collected.distinct || s.checked) + ' distinct, ' + s.checked + ' checked.'
);

const lines = [];
if (s.broken) { lines.push(s.broken + ' broken'); }
if (s.redirected) { lines.push(s.redirected + ' redirecting somewhere else'); }
if (s.blocked) { lines.push(s.blocked + ' blocked by a bot wall (not broken)'); }
if (lines.length) { parts.push(lines.join(', ') + '.'); }

if (!s.fresh_count) {
  parts.push('\nNothing new since the last run.');
} else {
  parts.push('\n*' + s.fresh_count + ' new since last time*');
  for (const f of s.fresh.slice(0, 15)) {
    parts.push(
      '\n' + (f.verdict === 'broken' ? ':x:' : ':arrow_right:') + ' ' + f.url +
      '\n   ' + f.detail +
      '\n   linked from ' + (f.found_on || 'unknown') + (f.times > 1 ? ' (+' + (f.times - 1) + ' more)' : '')
    );
  }
  if (s.fresh.length > 15) { parts.push('\n...and ' + (s.fresh.length - 15) + ' more.'); }
}

return [{ json: { message: parts.join('\n'), fresh_count: s.fresh_count } }];

// One row per problem, for the table that keeps the report quiet next week.
//
// Read from `Only The New Problems` by name, not from the input. The input here
// is the built report, which carries the message and the counts and not the
// rows - the first live run wrote nothing at all because of that, and a state
// table that never fills means the same findings again every Monday forever.
//
// single-item input: that step folds the whole run into one item, and this
// unfolds the part of it that has to be stored.
const s = $('Only The New Problems').first().json;
if (!s.fresh || !s.fresh.length) { return []; }
return s.fresh.map(function (f) { return { json: f }; });
